function renderMonth(){const y=shown.getUTCFullYear(),m=shown.getUTCMonth()+1,today=rigaNow();return `<table class="calendar-table" aria-label="${MONTHS[m-1]} ${y}"><thead><tr><th scope="col">Ned.</th>${SHORT.map((d,i)=>`<th scope="col" class="${i>4?'weekend':''}"><abbr title="${DAYS[i]}">${d}</abbr></th>`).join('')}</tr></thead><tbody>${monthGrid(y,m).map(w=>`<tr><td class="week-number"><a href="${w.year>=2027&&w.year<=2030?`/nedelas-kalendars/${w.year}/${pad(w.week)}/`:`/?date=${w.days[0].date}&amp;view=week`}" data-week-link="${w.year}-${w.week}" aria-label="${w.year}. gada ${w.week}. nedēļa">${w.week}</a></td>${w.days.map(d=>{const events=eventsFor(d.date),holidays=events.filter(e=>e.readonly);return `<td class="${d.inMonth?'':'other-month'} ${d.weekday>5?'weekend':''} ${d.date===today?'is-today':''} ${d.date===selected?'selected-day':''} ${holidays.some(h=>h.dayOff!==false)?'holiday':''}"><button class="day-button" data-date="${d.date}" aria-label="${esc(fmtDate(d.date,true))}${events.length?', notikumi: '+events.length:''}" ${d.date===today?'aria-current="date"':''}><span class="date-number">${d.day}</span>${events.slice(0,2).map(e=>`<span class="day-event"><i class="dot" style="background:${CATS[e.category]?.color||CATS.personal.color}"></i><span class="event-label">${esc((e.time?e.time+' ':'')+e.title)}</span></span>`).join('')}${events.length>2?`<span class="more-events">+${events.length-2}</span>`:''}</button></td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function eventRow(e){return `<div class="plan-event"><time>${esc(e.time||'Visu dienu')}</time><i class="dot" style="background:${CATS[e.category]?.color||CATS.personal.color}"></i>${e.readonly?`<div><strong>${esc(e.title)}</strong><small>${e.dayOff===false?'Atceres vai atzīmējamā diena':'Svētku diena'}</small></div>`:`<button class="event-edit" data-edit-event="${esc(e.id)}"><strong>${esc(e.title)}</strong><small>${CATS[e.category]?.label||'Personīgais'}${e.repeat&&e.repeat!=='none'?' · atkārtojas':''}</small></button>`}</div>`}
function renderWeek(){const start=plus(shown,-((shown.getUTCDay()+6)%7));return `<div class="week-view">${Array.from({length:7},(_,i)=>{const d=plus(start,i),key=iso(d),events=eventsFor(key);return `<section class="week-day ${key===rigaNow()?'is-today':''}"><button data-date="${key}"><span>${DAYS[i]}</span><strong>${d.getUTCDate()}</strong></button><div>${events.length?events.map(eventRow).join(''):'<p class="empty-state">Brīva diena plāniem</p>'}<button class="text-button" data-add-date="${key}">＋ Notikums</button></div></section>`}).join('')}</div>`}
function renderDay(){const key=iso(shown),events=eventsFor(key);return `<div class="day-timeline">${events.filter(e=>!e.time).map(eventRow).join('')}${Array.from({length:17},(_,i)=>{const hour=pad(i+6)+':00',items=events.filter(e=>e.time&&e.time.slice(0,2)===hour.slice(0,2));return `<div class="timeline-hour"><span>${hour}</span><div>${items.length?items.map(e=>`<button data-edit-event="${esc(e.id)}">${esc(e.time)} · ${esc(e.title)}</button>`).join(''):`<button class="text-button" data-add-date="${key}" data-time="${hour}" aria-label="Pievienot notikumu ${hour}">＋</button>`}</div></div>`}).join('')}</div>`}
function renderList(){const y=shown.getUTCFullYear(),m=shown.getUTCMonth(),last=new Date(Date.UTC(y,m+1,0)).getUTCDate();const rows=[];for(let day=1;day<=last;day++){const key=iso(new Date(Date.UTC(y,m,day))),ev=eventsFor(key);if(ev.length)rows.push(`<h3 class="list-date">${esc(fmtDate(key,true))}</h3>${ev.map(eventRow).join('')}`)}return `<div class="list-view">${rows.length?rows.join(''):'<p class="empty-state">Šajā mēnesī nav notikumu, kas atbilst izvēlētajiem filtriem. Pievienojiet savu pirmo notikumu vai ieslēdziet citas kategorijas.</p>'}</div>`}
function renderYear(){const year=shown.getUTCFullYear();return `<div class="year-grid">${MONTHS.map((name,mi)=>`<section class="mini-month"><button data-month="${mi+1}"><h3>${name}</h3></button><div class="mini-grid">${SHORT.map(d=>`<span class="mini-label">${d}</span>`).join('')}${monthGrid(year,mi+1).flatMap(w=>w.days).map(d=>`<button class="${d.inMonth?'':'other-month'} ${d.weekday>5?'weekend':''} ${d.date===rigaNow()?'is-today':''}" data-date="${d.date}" aria-label="${esc(fmtDate(d.date))}">${d.day}</button>`).join('')}</div></section>`).join('')}</div>`}
function renderCalendar(){if(!$('#calendar-app'))return;const y=shown.getUTCFullYear(),m=shown.getUTCMonth();let title=MONTHS[m]+' '+y;if(view==='year')title=y+'. gads';if(view==='week')title=week(shown).week+'. nedēļa · '+week(shown).year;if(view==='day')title=shown.getUTCDate()+'. '+MONTH_GEN[m]+' '+y;$('#calendar-title').textContent=title;$('#calendar-view').innerHTML=({month:renderMonth,week:renderWeek,day:renderDay,list:renderList,year:renderYear}[view]||renderMonth)();$$('button[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));const years=[...new Set([2027,2028,2029,2030,y])].sort();$('#calendar-year').innerHTML=years.map(n=>`<option value="${n}" ${n===y?'selected':''}>${n}</option>`).join('');$('#metric-week').textContent=week(parse(selected)).week;$('#metric-day').textContent=Math.round((parse(selected)-new Date(Date.UTC(+selected.slice(0,4),0,1)))/DAY)+1;$('#metric-month').textContent=new Date(Date.UTC(y,m+1,0)).getUTCDate();renderDayPanel();renderLayers()}
function renderDayPanel(){if(!$('#day-events'))return;$('#selected-day-label').textContent=fmtDate(selected,true);const ev=eventsFor(selected,true);$('#day-events').innerHTML=ev.length?ev.map(eventRow).join(''):'<p class="empty-state">Šī diena vēl ir brīva. Pievienojiet notikumu un atvēliet laiku svarīgākajam.</p>';$('#notes').value=store.notes[selected]||'';renderTasks()}
function renderTasks(){const el=$('#task-list');if(!el)return;el.innerHTML=store.tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><label><input type="checkbox" data-task-id="${esc(t.id)}" ${t.done?'checked':''}><span>${esc(t.title)}</span></label><button class="icon-button" data-delete-task="${esc(t.id)}" aria-label="Dzēst uzdevumu ${esc(t.title)}">×</button></div>`).join('')}
function selectDate(key){if(!parse(key))return;selected=key;shown=parse(key);if(view==='year')view='month';renderCalendar();if(innerWidth<=680)$('#day-events')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}
function eventDialog(id,date,time){const event=store.events.find(e=>e.id===id)||{date:date||selected,time:time||'',title:'',category:'personal',repeat:'none',description:''};dialog(id?'Rediģēt notikumu':'Jauns notikums',`<form id="event-form"><input type="hidden" name="eventId" value="${esc(id||'')}"><label>Notikuma nosaukums<input name="title" value="${esc(event.title)}" maxlength="200" required autocomplete="off"></label><div class="field-grid"><label>Datums<input type="date" name="date" value="${esc(event.date)}" required min="1900-01-01" max="2100-12-31"></label><label>Laiks (tukšs — visa diena)<input type="time" name="time" value="${esc(event.time||'')}"></label><label>Kategorija<select name="category">${Object.entries(CATS).filter(([k])=>k!=='holiday').map(([k,c])=>`<option value="${k}" ${event.category===k?'selected':''}>${c.label}</option>`).join('')}</select></label><label>Atkārtošanās<select name="repeat">${[['none','Neatkārtojas'],['daily','Katru dienu'],['weekly','Katru nedēļu'],['monthly','Katru mēnesi'],['yearly','Katru gadu']].map(([k,t])=>`<option value="${k}" ${event.repeat===k?'selected':''}>${t}</option>`).join('')}</select></label><label>Atkārtojuma beigas (neobligāti)<input type="date" name="until" value="${esc(event.until||'')}"></label><label>Intervāls<input type="number" name="interval" min="1" max="365" value="${event.interval||1}"></label></div><label>Piezīme<textarea name="description" maxlength="10000">${esc(event.description||'')}</textarea></label><p class="muted">Laika josla: Europe/Riga. Notikums tiek saglabāts tikai šajā pārlūkā. Atkārtota notikuma izmaiņas attiecas uz visu sēriju.</p><div class="actions">${id?`<button type="button" class="danger" data-delete-event="${esc(id)}">Dzēst notikumu</button>`:''}<button type="button" data-action="close-dialog">Atcelt</button><button class="primary">Saglabāt</button></div></form>`)}
function settingsDialog(){dialog('Kalendāra iestatījumi',`<form id="settings-form"><label>Izskats<select name="theme"><option value="system" ${store.theme==='system'?'selected':''}>Atbilstoši ierīces iestatījumam</option><option value="light" ${store.theme==='light'?'selected':''}>Gaišā tēma</option><option value="dark" ${store.theme==='dark'?'selected':''}>Tumšā tēma</option></select></label><label>Kalendāra skats<select name="view">${[['month','Mēnesis'],['week','Nedēļa'],['day','Diena'],['list','Saraksts'],['year','Gads']].map(([v,t])=>`<option value="${v}" ${view===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="notice"><strong>Privātums pēc noklusējuma.</strong><p>Notikumi, uzdevumi un piezīmes netiek nosūtīti uz serveri. Izveidojiet dublējumu pirms pārlūka datu dzēšanas.</p></div><div class="actions"><button type="button" data-action="backup">Dublēt datus</button><button type="button" data-action="clear-data" class="danger">Dzēst manus datus</button><button class="primary">Saglabāt</button></div></form>`)}
function backupDialog(){dialog('Kalendāra dublējums',`<p>Saglabājiet savus notikumus, uzdevumus un piezīmes JSON failā. Failu varēsiet atjaunot citā ierīcē. Glabājiet to drošā vietā — tas satur jūsu personiskos plānus.</p><div class="actions"><button class="primary" data-action="download-backup">Lejupielādēt dublējumu</button><button data-action="restore-backup">Atjaunot no faila</button></div><p class="muted">Atjaunošana aizstās pašreizējos notikumus, uzdevumus un piezīmes. Pirms tam lejupielādējiet pašreizējo dublējumu.</p>`)}
function consentDialog(){dialog('Sīkdatnes un vietējā krātuve',`<p>Kalendāra notikumi un jūsu izvēles tiek saglabātas šajā ierīcē. Šobrīd vietnē nav analītikas vai reklāmas izsekotāju.</p><label class="check-label"><input type="checkbox" checked disabled>Nepieciešamā kalendāra un izvēļu krātuve</label><p>Jūs varat dzēst savus datus kalendāra iestatījumos. Atteikšanās neierobežo kalendāra funkcijas.</p><div class="actions"><button data-consent="necessary">Noraidīt neobligātās</button><button class="primary" data-consent="all">Pieņemt izvēli</button></div><p><a href="/sikdatnu-politika/">Sīkdatņu politika</a> · <a href="/privatuma-politika/">Privātuma politika</a></p>`)}
async function getSearchIndex(){if(searchIndex)return searchIndex;const r=await fetch(assetURL('/assets/search-index.json'));if(!r.ok)throw Error('Meklēšanas dati pašlaik nav pieejami.');const raw=await r.json();searchIndex=Array.isArray(raw)?raw:raw.pages||raw.routes||[];return searchIndex}
async function doSearch(query,target){try{const idx=await getSearchIndex(),q=normalize(query).trim(),tokens=q.split(/\s+/).filter(Boolean);if(!q){target.innerHTML='<p class="empty-state">Meklējiet, piemēram, “2029 februāris”, “Jānis” vai “darba dienas”.</p>';return}const candidates=idx.map(r=>{const hay=normalize([r.title,r.name,r.description,r.path,r.url,r.family,r.keywords,r['Latvian title/topic'],r['URL path']].filter(Boolean).join(' '));const words=hay.split(/[^a-z0-9]+/);let score=tokens.reduce((v,t)=>v+(hay.includes(t)?12:t.length>3&&words.some(w=>nearWord(t,w))?10:0),0);if(normalize(r.title||'').includes(q))score+=20;return{r,score}}).filter(x=>x.score>=tokens.length*10).sort((a,b)=>b.score-a.score).slice(0,40);target.innerHTML=candidates.length?candidates.map(({r})=>{const url=r.url||r.path||r['URL path']||'/';return `<a class="search-result" href="${esc(url)}"><strong>${esc(r.title||r.name||r['Latvian title/topic']||url)}</strong><small>${esc(r.description||url)}</small></a>`}).join(''):'<p class="empty-state">Nekas nav atrasts. Pamēģiniet īsāku vārdu vai citu gadu. Var meklēt arī bez garumzīmēm.</p>'}catch(e){target.innerHTML=`<p class="dialog-message">${esc(e.message)}</p>`}}
function searchDialog(){dialog('Meklēt Kalendārā365','<form id="site-search-form" class="search-field"><input type="search" name="q" placeholder="Datums, vārds vai rīks…" aria-label="Meklēt vietnē" autocomplete="off"><button class="primary">Meklēt</button></form><div id="site-search-results" class="search-results"></div>');doSearch('',$('#site-search-results'))}
let printPromise;function loadPrint(){if(window.K365Print)return Promise.resolve(window.K365Print);if(!printPromise)printPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=assetURL('/assets/print.js');s.onload=()=>resolve(window.K365Print);s.onerror=()=>{printPromise=null;reject(Error('Neizdevās ielādēt drukas rīku. Lūdzu, mēģiniet vēlreiz.'))};document.head.append(s)});return printPromise}
const DESIGN_NAMES=['Karmīna klasika','Rīgas panorāma','Melnbalts arhīvs','Latvju rakstu josla','Mājīgs ģimenes plāns','Minimāls melnbalts','Dabas gadalaiki','Stingrais birojs','Mēness grafika','Ģeometriskais bordo','Skolas nedēļa','Smalkas līnijas','Maiņu maiņstrāva','Redaktora izkārtojums','Svētku ornaments'];
function currentPrintType(){const p=location.pathname,f=document.body.dataset.family||'';if(p.includes('meness')||p.includes('pilnmeness')||p.includes('jaunmeness'))return Number(document.body.dataset.month)?'lunar':'lunar-year';if(p.includes('mainu'))return'shift';if(p.includes('stundu')||p.includes('skolas'))return'school';if(p.includes('gimenes'))return'family';if(p.includes('tukss'))return'blank';if(p.includes('darba'))return Number(document.body.dataset.month)?'work':'work-year';if(p.includes('ar-vardu'))return'named';if(f==='iso_week'||p.includes('nedelas'))return'weekly';if(p.includes('dienas-planotajs')||p.includes('dienas-kalendars'))return'daily';return view==='year'||f==='year'?'yearly':'monthly'}
function customizeDialog(design=1){const year=Math.max(2027,Math.min(2030,shown.getUTCFullYear())),type=currentPrintType();dialog('Izveido savu kalendāru',`<form id="print-form"><div class="field-grid"><label>Kalendāra veids<select name="type">${[['yearly','Gada kalendārs'],['monthly','Mēneša kalendārs'],['weekly','Nedēļas plānotājs'],['daily','Dienas plānotājs'],['lunar','Mēness mēneša kalendārs'],['lunar-year','Mēness gada kalendārs'],['blank','Tukšs kalendārs'],['work','Darba dienu mēneša kalendārs'],['work-year','Darba dienu gada kalendārs'],['family','Ģimenes plāns'],['shift','Maiņu grafiks'],['school','Stundu saraksts'],['named','Kalendārs ar vārdu']].map(([k,t])=>`<option value="${k}" ${type===k?'selected':''}>${t}</option>`).join('')}</select></label><label>Dizains<select name="design">${DESIGN_NAMES.map((n,i)=>`<option value="${i+1}" ${i+1===Number(design)?'selected':''}>${pad(i+1)} · ${n}</option>`).join('')}</select></label><label>Gads<select name="year">${[2027,2028,2029,2030].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label>Mēnesis<select name="month">${MONTHS.map((m,i)=>`<option value="${i+1}" ${shown.getUTCMonth()===i?'selected':''}>${m}</option>`).join('')}</select></label><label>Datums (dienas vai nedēļas plānam)<input name="date" type="date" value="${year}-${pad(shown.getUTCMonth()+1)}-${pad(Math.min(shown.getUTCDate(),new Date(Date.UTC(year,shown.getUTCMonth()+1,0)).getUTCDate()))}" min="2027-01-01" max="2030-12-31"></label><label>Izvietojums<select name="orientation"><option value="portrait">A4 vertikāli</option><option value="landscape">A4 horizontāli</option></select></label></div><label>Vārds vai virsraksts (neobligāti)<input name="name" maxlength="80" value="${esc(document.body.dataset.name||'')}" placeholder="Piemēram, Emīlija"></label><label>Jūsu fotoattēls (neobligāti, līdz 10 MB)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="photo-controls" hidden><div class="photo-preview-frame"><img id="photo-preview" class="preview-photo" alt="Jūsu izvēlētā fotoattēla kadrējuma priekšskatījums"></div><div class="field-grid photo-adjustments"><label>Horizontālais novietojums<input type="range" name="photoX" min="0" max="1" step="0.01" value="0.5"></label><label>Vertikālais novietojums<input type="range" name="photoY" min="0" max="1" step="0.01" value="0.5"></label><label>Tuvinājums<input type="range" name="photoZoom" min="1" max="3" step="0.05" value="1"></label></div><p class="print-hint">Priekšskatījums palīdz izvēlēties kadrējumu; attēla laukums mainās atbilstoši kalendāra dizainam.</p></div><p class="print-hint">Fotoattēls paliek šajā ierīcē. PDF satur vektoru tekstu. WebP: 600 ppi A4 izmērā (4961 × 7016 vai 7016 × 4961 pikseļi); sagatavošana var aizņemt brīdi un izmantot ierīces atmiņu.</p><div class="actions"><button name="format" value="pdf" class="primary">Lejupielādēt PDF</button><button name="format" value="webp">Lejupielādēt WebP</button></div><p id="print-status" role="status"></p></form>`)}
function applyPrintContext(el){const ctx=el.closest('.print-section')?.dataset,form=$('#print-form');if(!ctx||!form)return;for(const [field,key] of [['type','printType'],['year','printYear'],['month','printMonth'],['name','printName']])if(ctx[key]&&form.elements[field])form.elements[field].value=ctx[key]}
async function generatePrint(options,button){const label=button?.textContent;try{if(button){button.disabled=true;button.textContent='Sagatavo…'}const api=await loadPrint();const result=await api.generate(options);toast(result.warning||'Fails ir sagatavots lejupielādei.');const status=$('#print-status');if(status)status.textContent=result.warning||'Fails ir sagatavots lejupielādei.'}catch(e){toast(e.message||'Failu neizdevās sagatavot. Mēģiniet PDF formātu.');const s=$('#print-status');if(s)s.textContent=e.message}finally{if(button){button.disabled=false;button.textContent=label}}}
function isWork(date,weekLength=5){try{if(window.CalendarCore?.isWorkday)return window.CalendarCore.isWorkday(date,{weekLength})}catch(e){}const d=typeof date==='string'?parse(date):date;return d.getUTCDay()!==0&&(weekLength===6||d.getUTCDay()!==6)&&!holidayList(d.getUTCFullYear()).some(h=>h.date===iso(d)&&h.dayOff!==false)}
function countWork(a,b,six=false){let start=parse(a),end=parse(b),sign=1;if(start>end){[start,end]=[end,start];sign=-1}let count=0;for(let d=start;d<=end;d=plus(d,1))if(isWork(d,six?6:5))count++;return count*sign}
function calcForm(form){const fd=new FormData(form),a=parse(fd.get('from')),b=parse(fd.get('to')),out=$('output',form);if(!a||!b){out.textContent='Lūdzu, ievadiet derīgus datumus.';return}if(Math.abs(b-a)>DAY*366*100){out.textContent='Izvēlieties periodu līdz 100 gadiem.';return}const work=fd.get('work'),days=work?countWork(iso(a),iso(b),fd.get('six')):Math.round((b-a)/DAY);out.textContent=work?`Darba dienu skaits: ${days}. Iekļauts sākuma un beigu datums; ${fd.get('six')?'6':'5'} dienu darba nedēļa. Pārceltās darbdienas nav piemērotas.`:`Dienu starpība: ${days}. Sākuma datums nav ieskaitīts.`;if(work&&(+iso(a).slice(0,4)<2027||+iso(b).slice(0,4)>2030))out.textContent+=' Pilnībā pārbaudītie svētku dati attiecas uz 2027.–2030. gadu.'}
function calculatorWidget(el){el.innerHTML=`<section class="tool-panel"><h2>Aprēķiniet laiku saviem plāniem</h2><form class="date-calculator"><div class="date-pair"><label>Sākuma datums<input type="date" name="from" required></label><label>Beigu datums<input type="date" name="to" required></label></div><div class="field-grid"><label class="check-label"><input type="checkbox" name="work" ${location.pathname.includes('darba')||location.pathname.includes('atvalinajuma')?'checked':''}>Skaitīt tikai darba dienas</label><label class="check-label"><input type="checkbox" name="six">Sešu dienu darba nedēļa</label></div><button class="primary">Aprēķināt</button><output class="tool-result" aria-live="polite"></output></form><p class="print-hint">Dienu starpība neietver sākuma datumu. Darba dienu aprēķins ietver abus datumus un izslēdz Latvijas svētku brīvdienas. Darbdienu pārcelšana un jūsu darba devēja īpašie noteikumi jāņem vērā atsevišķi.</p></section><section class="tool-panel"><h2>Pieskaitīt vai atņemt dienas</h2><form class="date-add-form"><div class="field-grid"><label>Datums<input type="date" name="date" value="${rigaNow()}" required></label><label>Dienu skaits<input type="number" name="days" value="30" min="-36500" max="36500" required></label></div><button>Aprēķināt datumu</button><output class="tool-result" aria-live="polite"></output></form></section>`}
function workWidget(el){const y=+(document.body.dataset.year||2027),rows=MONTHS.map((m,i)=>{let count=0,off=0;const last=new Date(Date.UTC(y,i+1,0)).getUTCDate();for(let d=1;d<=last;d++){const key=iso(new Date(Date.UTC(y,i,d)));if(isWork(key))count++;if(holidayList(y).some(h=>h.date===key&&h.dayOff!==false))off++}return`<tr><th scope="row"><a href="/darba-dienu-kalendars/${y}/${SLUGS[i]}/">${m}</a></th><td>${last}</td><td>${count}</td><td>${off}</td><td>${last-count}</td></tr>`});el.innerHTML=`<section class="tool-panel"><h2>${y}. gada darba un atpūtas dienas</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Mēnesis</th><th>Dienas</th><th>Darba dienas</th><th>Svētku dienas</th><th>Brīvdienas</th></tr></thead><tbody>${rows.join('')}</tbody></table></div><p class="print-hint">Pamataprēķins: pirmdiena–piektdiena, bez oficiālajām svētku brīvdienām. Valsts noteikta darbdienu pārcelšana nav piemērota. Svētku un nedēļas atpūtas dienas var pārklāties.</p></section>`;const calc=document.createElement('div');el.append(calc);calculatorWidget(calc)}
function namesWidget(el){const month=Number(document.body.dataset.month)||SLUGS.indexOf(location.pathname.split('/').filter(Boolean).at(-1))+1;el.innerHTML=`<section class="tool-panel"><h2>Atrodiet vārda dienu</h2><div class="field-grid"><label>Vārds<input type="search" class="name-query" placeholder="Piemēram, Jānis vai Emīlija"></label><label>Saraksts<select class="name-kind"><option value="all">Visi pieejamie vārdi</option value="traditional">Tradicionālais saraksts</option><option value="extended">Paplašinātais saraksts</option></select></label><label>Mēnesis<select class="name-month"><option value="0">Viss gads</option>${MONTHS.map((m,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${m}</option>`).join('')}</select></label></div><p class="name-count muted"></p><div class="names-results"></div></section>`;const update=()=>{const q=normalize($('.name-query',el).value),kind=$('.name-kind',el).value,m=Number($('.name-month',el).value);const list=data.names.filter(n=>(!q||normalize(n.name).includes(q))&&(!m||Number(n.month)===m)&&(kind==='all'||n.kind===kind));$('.name-count',el).textContent=data.names.length?`Atrasti vārdi: ${list.length}. Avots: VVC 2018. gada saraksts; pilna pārbaude pret 2026. gada sarakstu vēl nav pabeigta.`:'Oficiālo vārda dienu datu imports vēl nav pabeigts. Datumus neizdomājam.';$('.names-results',el).innerHTML=list.slice(0,150).map(n=>`<article class="name-result"><strong>${esc(n.name)}</strong><p>${Number(n.day)}. ${MONTH_GEN[Number(n.month)-1]}</p><small>${n.kind==='extended'?'Paplašinātais saraksts':'Tradicionālais saraksts'}</small><div class="actions"><button data-name-print="${esc(n.name)}">Savs kalendārs</button></div></article>`).join('')+(list.length>150?'<p class="muted">Parādīti pirmie 150 vārdi. Precizējiet meklēšanu.</p>':'')};$('.name-query',el).addEventListener('input',update);$('.name-kind',el).addEventListener('change',update);$('.name-month',el).addEventListener('change',update);update()}
function moonWidget(el){const year=+(document.body.dataset.year||2027),month=+document.body.dataset.month||0;el.innerHTML=`<section class="tool-panel"><h2>Mēness galvenās fāzes</h2><div class="field-grid"><label>Gads<select class="moon-year">${[2027,2028,2029,2030].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label>Mēnesis<select class="moon-month"><option value="0">Viss gads</option>${MONTHS.map((m,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="moon-grid"></div><p class="print-hint">Galveno fāžu notikumi: ASV Jūras observatorija (USNO). Laiks pārrēķināts uz Europe/Riga; vietējais datums var atšķirties no UTC datuma.</p></section>`;const update=()=>{const y=$('.moon-year',el).value,m=Number($('.moon-month',el).value),list=data.moon.filter(p=>p.date?.startsWith(y)&&(!m||Number(p.date.slice(5,7))===m));$('.moon-grid',el).innerHTML=list.length?list.map(p=>{const n=normalize(p.phaseKey||p.phase),symbol=n.includes('new')||n.includes('jaun')?'●':n.includes('full')||n.includes('piln')?'○':n.includes('first')||n.includes('pirma')?'◐':'◑';return`<article class="moon-card"><span class="moon-icon" aria-hidden="true">${symbol}</span><div><strong>${esc(p.phase)}</strong><time datetime="${esc(p.date)}">${esc(fmtDate(p.date))}</time><small>${esc(p.time||p.localTime||'')} · Rīgas laiks</small></div></article>`}).join(''):'<p class="empty-state">Pārbaudītie fāžu dati šim periodam vēl nav pieejami.</p>'};$('.moon-year',el).addEventListener('change',update);$('.moon-month',el).addEventListener('change',update);update()}
async function printWidget(el){const context=el.closest('.print-section')?.dataset||{};const y=+(context.printYear||document.body.dataset.year||2027),m=+(context.printMonth||document.body.dataset.month||1),type=context.printType||currentPrintType();el.innerHTML=`<section class="tool-panel"><div class="card-heading"><div><h2>15 dizaini jūsu kalendāram</h2><p class="muted">A4 · vektoru PDF · 600 ppi WebP · krāsaini un melnbalti</p></div><button class="primary" data-action="customize">Pielāgot</button></div><div class="design-gallery">${DESIGN_NAMES.map((n,i)=>`<article class="design-card"><button data-design="${i+1}" aria-label="Pielāgot dizainu ${esc(n)}"><div class="design-preview" data-preview="${i+1}"><div class="design-paper"><strong>${y}</strong><i></i></div></div><h3>${pad(i+1)} · ${n}</h3><p>${[3,6,8,12,14].includes(i+1)?'Melnbalts':'Krāsains'} · A4</p></button><div class="actions"><button data-quick-print="pdf" data-design-id="${i+1}" data-print-year="${y}" data-print-month="${m}" data-print-type="${type}">↓ PDF</button><button data-quick-print="webp" data-design-id="${i+1}" data-print-year="${y}" data-print-month="${m}" data-print-type="${type}">↓ WebP</button></div></article>`).join('')}</div><p class="print-hint">Katra izvēle izveido īstu failu jūsu ierīcē. PDF teksts ir atlasāms, fonti ir iegulti. Lieli WebP faili var prasīt vairāk atmiņas; mobilajā ierīcē ieteicams sākt ar PDF.</p></section>`;try{const r=await fetch(assetURL('/downloads/manifest.json'));if(!r.ok)return;const manifest=await r.json();$$('[data-preview]',el).forEach(p=>{const item=(manifest.items||[]).find(it=>it.design===Number(p.dataset.preview)&&it.type===type&&it.year===y&&(!['monthly','lunar','work'].includes(type)||it.month===m))||(manifest.items||[]).find(it=>it.design===Number(p.dataset.preview)&&it.type===type);if(item?.preview)p.innerHTML=`<img src="${esc(assetURL(item.preview))}" alt="${esc(DESIGN_NAMES[Number(p.dataset.preview)-1])} — dizaina priekšskatījums" loading="lazy" width="110" height="145" style="width:100%;height:100%;object-fit:contain">`})}catch(e){}}
